INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-ca26-7539-9d64-3dcb82394224'::uuid, '019f9df7-a2a2-7839-8287-1e75e9dd37f8'::uuid, 'A car costs $72,000. A buyer pays a 25% downpayment and borrows the balance for 5 years at 2.8% simple interest per year. Find the total repayment on the loan.', '$61,560', 'Loan amount = 75% × 72,000 = $54,000. Interest = 54,000 × 0.028 × 5 = $7,560. Total repayment = 54,000 + 7,560 = $61,560.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.422Z'::timestamptz, '2026-08-15T07:50:40.422Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-ca2f-7572-805f-0ecd5b58bf45'::uuid, '019f9df7-a2a2-7839-8287-1e75e9dd37f8'::uuid, 'A shop buys an item for $240 and sells it for $306. Find the percentage profit.', '27.5%', 'Profit = 306 - 240 = $66. Percentage profit = (66 / 240) × 100% = 27.5%.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.431Z'::timestamptz, '2026-08-15T07:50:40.431Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-ca38-7977-bfa6-3578c2d5c0c2'::uuid, '019f9df7-a2a2-78fc-bd9e-a40e9b4f9363'::uuid, 'A cuboid has volume 720 cm³ and a square base. The side length of its base is greater than 3 cm. Find the smallest possible integer height.', '5 cm', 'Square factors of 720 with side > 3 include 16 (s=4, h=45), 36 (s=6, h=20), and 144 (s=12, h=5). The smallest integer height is 5 cm.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.440Z'::timestamptz, '2026-08-15T07:50:40.440Z'::timestamptz) ON CONFLICT (id) DO NOTHING;